#!/usr/bin/env python3
"""
Process HWPX template: replace {{...}} placeholders with JSON values.
Handles transformation rules and removes layout cache elements.
"""

import json
import re
import os
import xml.etree.ElementTree as ET
import shutil

# Register namespaces to preserve them during write
ET.register_namespace('hp', 'http://www.hancom.co.kr/hwpml/2010/HWPML')

def load_json_data(json_path):
    """Load and return the JSON data."""
    with open(json_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def transform_value(key, value):
    """Apply transformation rules based on the key."""
    if key == '참석자수':
        # Extract digits only
        match = re.search(r'\d+', str(value))
        return match.group(0) if match else str(value)

    elif key == '만족도':
        # Extract numeric part and format as "X.X점 (5.0점 만점)"
        match = re.search(r'([\d.]+)', str(value))
        if match:
            score = match.group(1)
            return f"{score}점 (5.0점 만점)"
        return str(value) + "점 (5.0점 만점)"

    elif key == '종합의견':
        # Append suffix with proper spacing
        suffix = "후속 심화반 검토 요망."
        value_str = str(value)
        if value_str.endswith(' '):
            return value_str + suffix
        else:
            return value_str + ' ' + suffix

    else:
        # Direct replacement
        return str(value)

def remove_layout_cache(p_elem):
    """Remove layout cache child elements from a paragraph."""
    # Elements to remove (common layout cache elements in HWP XML)
    layout_cache_tags = [
        'linesegarray',
        'lineSegArray',
        'lineseg',
        'lineSeg',
        '{http://www.hancom.co.kr/hwpml/2010/HWPML}linesegarray',
        '{http://www.hancom.co.kr/hwpml/2010/HWPML}lineseg',
    ]

    to_remove = []
    for child in p_elem:
        # Check tag with and without namespace
        tag = child.tag
        if any(cache_tag in tag.lower() for cache_tag in layout_cache_tags):
            to_remove.append(child)

    for child in to_remove:
        p_elem.remove(child)

def process_xml_file(xml_path, data):
    """Process a single XML file, replacing placeholders."""
    tree = ET.parse(xml_path)
    root = tree.getroot()

    # Namespace
    ns = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

    modified = False

    # Find all paragraphs
    for p_elem in root.iter():
        if 'p' in p_elem.tag and p_elem.tag.endswith('}'):
            # Collect all text content from this paragraph
            paragraph_text = ''
            text_elements = []  # List of (run_element, t_element) tuples

            for run_elem in p_elem.iter():
                if 'run' in run_elem.tag and run_elem.tag.endswith('}'):
                    for t_elem in run_elem:
                        if 't' in t_elem.tag and t_elem.tag.endswith('}'):
                            if t_elem.text:
                                paragraph_text += t_elem.text
                            text_elements.append((run_elem, t_elem))

            # Check for placeholders in the concatenated text
            if '{{' in paragraph_text and '}}' in paragraph_text:
                # Find all placeholders
                placeholders = re.findall(r'\{\{(\w+)\}\}', paragraph_text)

                if placeholders:
                    modified = True
                    modified_text = paragraph_text

                    # Replace each placeholder
                    for ph in placeholders:
                        if ph in data:
                            transformed = transform_value(ph, data[ph])
                            modified_text = modified_text.replace(f'{{{{{ph}}}}}', transformed)

                    # If text was modified, redistribute to first text element, clear others
                    if modified_text != paragraph_text:
                        first = True
                        for run_elem, t_elem in text_elements:
                            if first:
                                t_elem.text = modified_text
                                first = False
                            else:
                                t_elem.text = ''

                    # Remove layout cache elements from modified paragraph
                    remove_layout_cache(p_elem)

    # Write back if modified
    if modified:
        tree.write(xml_path, encoding='utf-8', xml_declaration=True)

    return modified

def verify_no_placeholders(xml_path):
    """Verify no {{placeholders}} remain in the file."""
    with open(xml_path, 'r', encoding='utf-8') as f:
        content = f.read()
    remaining = re.findall(r'\{\{.*?\}\}', content)
    return remaining

def main():
    # Paths
    json_path = '/root/training_feedback.json'
    template_dir = '/tmp/hwpx_work/template_extracted'
    output_file = '/root/training_feedback_ready.hwpx'

    # Load data
    data = load_json_data(json_path)
    print(f"Loaded data: {list(data.keys())}")

    # Process both XML files
    xml_files = [
        os.path.join(template_dir, 'Contents', 'section0.xml'),
        os.path.join(template_dir, 'Contents', 'section1.xml'),
    ]

    for xml_path in xml_files:
        if os.path.exists(xml_path):
            print(f"\nProcessing {xml_path}...")
            modified = process_xml_file(xml_path, data)
            print(f"  Modified: {modified}")

            # Verify no placeholders remain
            remaining = verify_no_placeholders(xml_path)
            if remaining:
                print(f"  WARNING: Placeholders remain: {remaining}")
            else:
                print(f"  All placeholders replaced successfully")

    # Repackage as HWPX
    print(f"\nRepackaging to {output_file}...")
    with shutil.ZipFile(output_file, 'w') as zipf:
        for root, dirs, files in os.walk(template_dir):
            for file in files:
                file_path = os.path.join(root, file)
                arcname = os.path.relpath(file_path, template_dir)
                zipf.write(file_path, arcname)

    print(f"Output written to: {output_file}")

    # Final verification
    print("\n--- Final Verification ---")
    with shutil.ZipFile(output_file, 'r') as zipf:
        content = zipf.read('Contents/section0.xml').decode('utf-8')
        content += zipf.read('Contents/section1.xml').decode('utf-8')

        # Check for remaining placeholders
        remaining = re.findall(r'\{\{.*?\}\}', content)
        print(f"Remaining placeholders: {len(remaining)}")

        # Check for expected transformed values
        if '후속 심화반 검토 요망' in content:
            print("✓ 종합의견 transformation applied")
        else:
            print("✗ 종합의견 transformation NOT found")

        if '점 (5.0점 만점)' in content:
            print("✓ 만족도 transformation applied")
        else:
            print("✗ 만족도 transformation NOT found")

        # Check 참석자수 is digits only (should be "32" not "32명")
        if re.search(r'참석자 수: \d+(?![\w])', content):
            print("✓ 참석자수 is digits only")
        else:
            print("✗ 참석자수 may still have non-digit characters")

if __name__ == '__main__':
    main()

